function loadWorkflowRuntime() {
  if (ReactFlow) return Promise.resolve();
  if (!workflowRuntimePromise) {
    workflowRuntimePromise = Promise.all([
      import("@xyflow/react"),
      import("@xyflow/react/dist/style.css"),
    ]).then(([module]) => {
      ({
        ReactFlow,
        BaseEdge,
        Background,
        Handle,
        MiniMap,
        Position,
        SelectionMode,
        addEdge,
        getBezierPath,
        useEdgesState,
        useNodesState,
        useUpdateNodeInternals,
      } = module);
    });
  }
  return workflowRuntimePromise;
}

function WorkflowRuntimeLoader({ children }) {
  const [ready, setReady] = useState(Boolean(ReactFlow));
  useEffect(() => {
    let active = true;
    void loadWorkflowRuntime().then(() => active && setReady(true));
    return () => {
      active = false;
    };
  }, []);
  return ready ? children : <RouteLoadingFallback />;
}
