function parseShotPlan(value, totalDuration) {
  const shots = String(value || "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line, index) => {
      const separator = line.indexOf("|");
      if (separator < 1)
        throw new Error(`第 ${index + 1} 个分镜请使用“秒数 | 提示词”格式`);
      const duration = Number(line.slice(0, separator).trim());
      const prompt = line.slice(separator + 1).trim();
      if (!Number.isInteger(duration) || duration < 1 || !prompt)
        throw new Error(`第 ${index + 1} 个分镜的秒数或提示词无效`);
      if (prompt.length > 512)
        throw new Error(`第 ${index + 1} 个分镜超过 512 字`);
      return { index: index + 1, duration, prompt };
    });
  if (!shots.length || shots.length > 6)
    throw new Error("Omni 自定义分镜需填写 1–6 行");
  if (
    shots.reduce((sum, shot) => sum + shot.duration, 0) !==
    Number(totalDuration)
  )
    throw new Error(`自定义分镜时长之和必须等于 ${totalDuration} 秒`);
  return shots;
}

