const fileExtension = (file) =>
  String(file?.name || "")
    .split(".")
    .pop()
    .toLowerCase();
const isAnalysisVideoFile = (file) =>
  VIDEO_ANALYSIS_MIME_TYPES.has(String(file?.type || "").toLowerCase()) ||
  VIDEO_ANALYSIS_EXTENSIONS.has(fileExtension(file));
const mediaKind = (file) =>
  file?.type?.startsWith("image/")
    ? "image"
    : file?.type?.startsWith("video/") || isAnalysisVideoFile(file)
      ? "video"
      : file?.type?.startsWith("audio/")
        ? "audio"
        : "unknown";
const isAudioSourceFile = (file) =>
  AUDIO_SOURCE_ACCEPT.has(String(file?.type || "").toLowerCase());
const fileSize = (bytes) =>
  bytes >= 1024 * 1024
    ? `${(bytes / 1024 / 1024).toFixed(1)} MB`
    : `${Math.ceil(bytes / 1024)} KB`;

function validateMediaFiles(fileList, allowedKinds, limits = {}) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    const kind = mediaKind(file);
    const maxCount = limits[kind] ?? Infinity;
    if (
      !allowedKinds.includes(kind) ||
      !MEDIA_ACCEPT[kind]?.includes(file.type)
    )
      rejected.push(`${file.name} 格式不支持`);
    else if (file.size > MEDIA_LIMITS[kind])
      rejected.push(`${file.name} 超过 ${MEDIA_LIMITS[kind] / 1024 / 1024}MB`);
    else if (
      accepted.filter((item) => mediaKind(item) === kind).length >= maxCount
    )
      rejected.push(
        `${kind === "image" ? "图片" : kind === "video" ? "视频" : "音频"}数量已达上限`,
      );
    else accepted.push(file);
  }
  return { accepted, rejected };
}

function validateAnalysisVideoFiles(fileList, maxCount = 3) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    if (!isAnalysisVideoFile(file))
      rejected.push(`${file.name} 不是可分析的视频格式`);
    else if (file.size > VIDEO_ANALYSIS_MAX_BYTES)
      rejected.push(`${file.name} 超过 80MB`);
    else if (accepted.length >= maxCount) rejected.push("分析视频数量已达上限");
    else accepted.push(file);
  }
  return { accepted, rejected };
}

function validateAnalysisMixedFiles(fileList, limits = { image: 9, video: 3 }) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    const kind = mediaKind(file);
    if (kind === "image") {
      if (!MEDIA_ACCEPT.image.includes(file.type))
        rejected.push(`${file.name} 图片格式不支持`);
      else if (file.size > MEDIA_LIMITS.image)
        rejected.push(
          `${file.name} 超过 ${MEDIA_LIMITS.image / 1024 / 1024}MB`,
        );
      else if (
        accepted.filter((item) => mediaKind(item) === "image").length >=
        limits.image
      )
        rejected.push("图片数量已达上限");
      else accepted.push(file);
    } else if (kind === "video") {
      const result = validateAnalysisVideoFiles(
        [file],
        accepted.filter((item) => mediaKind(item) === "video").length <
          limits.video
          ? 1
          : 0,
      );
      if (result.accepted.length) accepted.push(file);
      else rejected.push(result.rejected[0]);
    } else rejected.push(`${file.name} 格式不支持`);
  }
  return { accepted, rejected };
}

function validateAudioSourceFiles(fileList, maxCount = 3) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    const videoSource = file?.type?.startsWith("video/");
    const maxSize = videoSource ? MEDIA_LIMITS.video : MEDIA_LIMITS.audio;
    if (!isAudioSourceFile(file)) rejected.push(`${file.name} 格式不支持`);
    else if (file.size > maxSize)
      rejected.push(`${file.name} 超过 ${maxSize / 1024 / 1024}MB`);
    else if (accepted.length >= maxCount) rejected.push("参考声音数量已达上限");
    else accepted.push(file);
  }
  return { accepted, rejected };
}

function validateSeedanceFiles(fileList, kind, maxCount) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    const fileKind = mediaKind(file);
    const audioVideo = kind === "audio" && fileKind === "video";
    const acceptedType =
      kind === "audio"
        ? isAudioSourceFile(file)
        : fileKind === kind && MEDIA_ACCEPT[kind]?.includes(file.type);
    const maxSize = audioVideo
      ? SEEDANCE_UPLOAD_LIMITS.audioVideo
      : SEEDANCE_UPLOAD_LIMITS[kind];
    if (!acceptedType) rejected.push(`${file.name} 格式不支持`);
    else if (file.size > maxSize)
      rejected.push(
        `${file.name} 超过 ${maxSize / 1024 / 1024}MB，无法安全自动优化`,
      );
    else if (accepted.length >= maxCount)
      rejected.push(
        `${kind === "image" ? "图片" : kind === "video" ? "视频" : "音频"}数量已达上限`,
      );
    else accepted.push(file);
  }
  return { accepted, rejected };
}

function validateMiniMaxH3Files(fileList, kind, maxCount) {
  const accepted = [];
  const rejected = [];
  const allowed = {
    image: new Set(["image/jpeg", "image/jpg", "image/png", "image/webp", "image/heic", "image/heif"]),
    video: new Set(["video/mp4", "video/quicktime"]),
    audio: new Set(["audio/mpeg", "audio/mp3", "audio/wav", "audio/x-wav"]),
  }[kind];
  for (const file of Array.from(fileList || [])) {
    if (!allowed?.has(String(file?.type || "").toLowerCase()))
      rejected.push(`${file.name} 格式不支持`);
    else if (file.size > MINIMAX_H3_UPLOAD_LIMITS[kind])
      rejected.push(`${file.name} 超过 ${MINIMAX_H3_UPLOAD_LIMITS[kind] / 1024 / 1024}MB`);
    else if (accepted.length >= maxCount)
      rejected.push(`${kind === "image" ? "图片" : kind === "video" ? "视频" : "音频"}数量已达上限`);
    else accepted.push(file);
  }
  return { accepted, rejected };
}

function validateMiniMaxH3MixedFiles(fileList, allowedKinds, limits) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    const kind = mediaKind(file);
    if (!allowedKinds.includes(kind)) {
      rejected.push(`${file.name} 格式不支持`);
      continue;
    }
    const remaining = Math.max(
      0,
      Number(limits[kind] || 0) -
        accepted.filter((item) => mediaKind(item) === kind).length,
    );
    const result = validateMiniMaxH3Files([file], kind, remaining);
    if (result.accepted.length) accepted.push(result.accepted[0]);
    else rejected.push(...result.rejected);
  }
  return { accepted, rejected };
}

function inspectMiniMaxH3MediaMetadata(file, kind) {
  const cached = miniMaxH3MediaMetadata.get(file);
  if (cached) return Promise.resolve(cached);
  if (!(file instanceof File) || !["image", "video", "audio"].includes(kind))
    return Promise.resolve(null);
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    let settled = false;
    let timeoutId = null;
    let element = null;
    const finish = (metadata = null) => {
      if (settled) return;
      settled = true;
      if (timeoutId) globalThis.clearTimeout(timeoutId);
      if (element) {
        element.onload = null;
        element.onerror = null;
        element.onloadedmetadata = null;
        element.src = "";
      }
      URL.revokeObjectURL(url);
      const inspected = metadata
        ? {
            mimeType: String(file.type || "").toLowerCase(),
            sizeBytes: Number(file.size || 0),
            ...metadata,
          }
        : null;
      if (inspected) miniMaxH3MediaMetadata.set(file, inspected);
      resolve(inspected);
    };
    timeoutId = globalThis.setTimeout(() => finish(), 5000);
    if (kind === "image") {
      element = new Image();
      element.onload = () =>
        finish({
          width: Number(element.naturalWidth || 0),
          height: Number(element.naturalHeight || 0),
        });
      element.onerror = () => finish();
      element.src = url;
      return;
    }
    element = document.createElement(kind === "audio" ? "audio" : "video");
    element.preload = "metadata";
    element.onloadedmetadata = () =>
      finish({
        ...(kind === "video"
          ? {
              width: Number(element.videoWidth || 0),
              height: Number(element.videoHeight || 0),
            }
          : {}),
        durationSeconds: Number(element.duration),
      });
    element.onerror = () => finish();
    element.src = url;
  });
}

function miniMaxH3MetadataError(file, kind, metadata) {
  if (!metadata) return "";
  const label = file?.name || "素材";
  if (["image", "video"].includes(kind)) {
    const width = Number(metadata.width);
    const height = Number(metadata.height);
    if (Number.isFinite(width) && Number.isFinite(height) && width && height) {
      if (
        width < MINIMAX_H3_MEDIA_LIMITS.minimumDimension ||
        width > MINIMAX_H3_MEDIA_LIMITS.maximumDimension ||
        height < MINIMAX_H3_MEDIA_LIMITS.minimumDimension ||
        height > MINIMAX_H3_MEDIA_LIMITS.maximumDimension
      )
        return `${label} 宽高需在 256–5760 像素之间`;
      const ratio = width / height;
      if (
        ratio < MINIMAX_H3_MEDIA_LIMITS.minimumAspectRatio ||
        ratio > MINIMAX_H3_MEDIA_LIMITS.maximumAspectRatio
      )
        return `${label} 宽高比需在 0.4–2.5 之间`;
    }
  }
  if (["video", "audio"].includes(kind)) {
    const durationSeconds = Number(metadata.durationSeconds);
    if (
      Number.isFinite(durationSeconds) &&
      durationSeconds > 0 &&
      (durationSeconds < MINIMAX_H3_MEDIA_LIMITS.minimumDuration ||
        durationSeconds > MINIMAX_H3_MEDIA_LIMITS.maximumDuration)
    )
      return `${label} 时长需在 2–15 秒之间`;
  }
  return "";
}

async function validateMiniMaxH3MetadataForFiles(files) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(files || [])) {
    const kind = mediaKind(file);
    const metadata = await inspectMiniMaxH3MediaMetadata(file, kind);
    const error = miniMaxH3MetadataError(file, kind, metadata);
    if (error) rejected.push(error);
    else accepted.push(file);
  }
  return { accepted, rejected };
}

async function validateMiniMaxH3FilesWithMetadata(fileList, kind, maxCount) {
  const base = validateMiniMaxH3Files(fileList, kind, maxCount);
  const inspected = await validateMiniMaxH3MetadataForFiles(base.accepted);
  return {
    accepted: inspected.accepted,
    rejected: [...base.rejected, ...inspected.rejected],
  };
}

const knownMiniMaxH3MediaDuration = (files) =>
  Array.from(files || []).reduce(
    (total, file) =>
      total +
      Number(miniMaxH3MediaMetadata.get(file)?.durationSeconds || 0),
    0,
  );

function validateSeedanceMixedFiles(fileList, allowedKinds, limits) {
  const accepted = [];
  const rejected = [];
  for (const file of Array.from(fileList || [])) {
    const kind = mediaKind(file);
    if (!allowedKinds.includes(kind)) {
      rejected.push(`${file.name} 格式不支持`);
      continue;
    }
    const result = validateSeedanceFiles(
      [file],
      kind,
      Math.max(
        0,
        (limits[kind] ?? 0) -
          accepted.filter((item) => mediaKind(item) === kind).length,
      ),
    );
    accepted.push(...result.accepted);
    rejected.push(...result.rejected);
  }
  return { accepted, rejected };
}

const fileIdentity = (file) =>
  `${file?.name || ""}:${file?.size || 0}:${file?.lastModified || 0}`;
function uniqueIncomingFiles(current, incoming) {
  const seen = new Set(current.map(fileIdentity));
  const files = Array.from(incoming || []).filter(
    (file) => !seen.has(fileIdentity(file)) && seen.add(fileIdentity(file)),
  );
  return {
    files,
    duplicates: Array.from(incoming || []).length - files.length,
  };
}
function appendUniqueFiles(current, incoming, maximum) {
  const seen = new Set(current.map(fileIdentity));
  const unique = incoming.filter(
    (file) => !seen.has(fileIdentity(file)) && seen.add(fileIdentity(file)),
  );
  return {
    files: [...current, ...unique].slice(0, maximum),
    duplicates: incoming.length - unique.length,
  };
}

const COMMON_MEDIA_RATIOS = [
  "9:16",
  "1:2",
  "2:3",
  "3:4",
  "4:5",
  "1:1",
  "5:4",
  "4:3",
  "3:2",
  "2:1",
  "16:9",
];
function nearestMediaRatio(width, height) {
  if (!width || !height) return "9:16";
  const value = width / height;
  return COMMON_MEDIA_RATIOS.reduce((best, ratio) => {
    const [w, h] = ratio.split(":").map(Number);
    const [bestW, bestH] = best.split(":").map(Number);
    return Math.abs(Math.log(value / (w / h))) <
      Math.abs(Math.log(value / (bestW / bestH)))
      ? ratio
      : best;
  }, COMMON_MEDIA_RATIOS[0]);
}

function inspectMediaAsset(file) {
  const kind = mediaKind(file);
  const url = kind === "audio" ? "" : URL.createObjectURL(file);
  if (!url) return Promise.resolve({ file, kind, url });
  return new Promise((resolve) => {
    const finish = (width, height) =>
      resolve({
        file,
        kind,
        url,
        width,
        height,
        aspectRatio: nearestMediaRatio(width, height),
      });
    if (kind === "image") {
      const image = new Image();
      image.onload = () => finish(image.naturalWidth, image.naturalHeight);
      image.onerror = () => finish(0, 0);
      image.src = url;
      return;
    }
    const video = document.createElement("video");
    video.preload = "metadata";
    video.onloadedmetadata = () => finish(video.videoWidth, video.videoHeight);
    video.onerror = () => finish(0, 0);
    video.src = url;
  });
}

const IMAGE_API_SAFE_PIXELS = 35_000_000;
const IMAGE_API_SAFE_EDGE = 4096;
const IMAGE_API_UPLOAD_BYTES = 48 * 1024 * 1024;

async function normalizeImageFileForApi(file) {
  if (!(file instanceof File) || mediaKind(file) !== "image")
    throw new Error("请选择有效的图片文件");
  let bitmap;
  try {
    bitmap = await createImageBitmap(file, { imageOrientation: "from-image" });
  } catch {
    throw new Error(`${file.name} 无法读取，请重新导出为 JPG、PNG 或 WebP`);
  }
  const originalWidth = bitmap.width;
  const originalHeight = bitmap.height;
  const scale = Math.min(
    1,
    IMAGE_API_SAFE_EDGE / originalWidth,
    IMAGE_API_SAFE_EDGE / originalHeight,
    Math.sqrt(IMAGE_API_SAFE_PIXELS / (originalWidth * originalHeight)),
  );
  const width = Math.max(2, Math.floor((originalWidth * scale) / 2) * 2);
  const height = Math.max(2, Math.floor((originalHeight * scale) / 2) * 2);
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d", { alpha: true });
  if (!context) {
    bitmap.close?.();
    throw new Error(`${file.name} 无法创建图片处理画布`);
  }
  context.drawImage(bitmap, 0, 0, width, height);
  bitmap.close?.();
  const outputType =
    file.type === "image/jpeg" || file.type === "image/jpg"
      ? "image/jpeg"
      : "image/png";
  const blob = await new Promise((resolve) =>
    canvas.toBlob(
      resolve,
      outputType,
      outputType === "image/jpeg" ? 0.92 : undefined,
    ),
  );
  if (!blob) throw new Error(`${file.name} 自动优化失败，请更换图片后重试`);
  const extension = outputType === "image/jpeg" ? "jpg" : "png";
  const normalized = new File(
    [blob],
    `${String(file.name || "reference").replace(/\.[^.]+$/, "")}.${extension}`,
    { type: outputType, lastModified: file.lastModified || Date.now() },
  );
  return {
    file: normalized,
    originalWidth,
    originalHeight,
    width,
    height,
    originalBytes: file.size,
    bytes: normalized.size,
    optimized:
      width !== originalWidth ||
      height !== originalHeight ||
      normalized.size < file.size ||
      normalized.type !== file.type,
  };
}

async function uploadWorkflowFile(file, inputKind) {
  return api.uploadWorkflowAssetFile(
    file,
    isAudioInputKind(inputKind) ? "audio" : mediaKind(file),
  );
}

async function mapWithConcurrency(items, limit, mapper) {
  const values = Array.from(items || []);
  if (!values.length) return [];
  const results = new Array(values.length);
  let cursor = 0;
  let firstError = null;
  const worker = async () => {
    while (cursor < values.length && !firstError) {
      const index = cursor;
      cursor += 1;
      try {
        results[index] = await mapper(values[index], index);
      } catch (error) {
        firstError ||= error;
      }
    }
  };
  await Promise.all(
    Array.from(
      { length: Math.min(Math.max(1, Number(limit) || 1), values.length) },
      worker,
    ),
  );
  if (firstError) throw firstError;
  return results;
}

function createAbortError() {
  const error = new Error("操作已取消");
  error.name = "AbortError";
  return error;
}

function isAbortError(error) {
  return error?.name === "AbortError";
}

async function uploadWorkflowRuntimeAssets(entries, inputKindForNode) {
  const groups = Array.from(entries || []).map(([nodeId, files]) => ({
    nodeId,
    files: (files || []).filter((file) => file instanceof File),
  }));
  const jobs = groups.flatMap((group) =>
    group.files.map((file, fileIndex) => ({
      nodeId: group.nodeId,
      file,
      fileIndex,
    })),
  );
  const uploaded = await mapWithConcurrency(jobs, 4, async (job) => ({
    ...job,
    asset: await uploadWorkflowFile(
      job.file,
      inputKindForNode(job.nodeId),
    ),
  }));
  const byNode = new Map(groups.map((group) => [group.nodeId, []]));
  uploaded.forEach(({ nodeId, fileIndex, asset }) => {
    byNode.get(nodeId)[fileIndex] = asset;
  });
  return Object.fromEntries(
    [...byNode.entries()].filter(([, assets]) => assets.length),
  );
}

function videoFileDuration(file) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const video = document.createElement("video");
    const finish = (value) => {
      URL.revokeObjectURL(url);
      resolve(Number.isFinite(value) ? Math.max(1, Math.round(value)) : 15);
    };
    video.preload = "metadata";
    video.onloadedmetadata = () => finish(video.duration);
    video.onerror = () => finish(15);
    video.src = url;
  });
}

