const RemovableEdge = memo(function RemovableEdge({
  sourceX,
  sourceY,
  targetX,
  targetY,
  sourcePosition,
  targetPosition,
  markerEnd,
  style,
  animated,
  data,
}) {
  const [path] = getBezierPath({
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
  });
  const referencePathActive = Boolean(data?.referencePathActive);
  const referenceFeedbackKey = data?.referenceFeedbackKey || "reference";
  return (
    <>
      <BaseEdge
        path={path}
        markerEnd={markerEnd}
        style={style}
        className={[
          animated ? "flow-edge-running" : "",
          referencePathActive ? "flow-edge-reference" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        interactionWidth={26}
      />
      {referencePathActive && (
        <circle
          key={referenceFeedbackKey}
          className="flow-edge-reference-marker"
          r="2.4"
          fill="#efffa7"
          opacity="0"
          pointerEvents="none"
        >
          <animate
            attributeName="opacity"
            values="0;0.96;0.58;0.92;0"
            keyTimes="0;0.14;0.5;0.82;1"
            dur="1.65s"
            repeatCount="indefinite"
          />
          <animate
            attributeName="r"
            values="2.1;3.4;2.5;3.2;2.1"
            keyTimes="0;0.18;0.5;0.8;1"
            dur="1.65s"
            repeatCount="indefinite"
          />
          <animateMotion
            path={path}
            dur="1.65s"
            repeatCount="indefinite"
          />
        </circle>
      )}
    </>
  );
});

