const QUICK_NEXT_NODE_KINDS = {
  "text-input": ["text", "text-preview", "image", "video", "audio-generation"],
  input: ["media-analysis", "image", "video", "face-input", "person-video-input"],
  "batch-input": ["image", "video"],
  "face-input": ["image", "asset", "video"],
  "person-video-input": ["media-analysis", "video"],
  audio: ["video"],
  "audio-reference": ["video"],
  "audio-generation": ["video", "preview", "output"],
  text: ["text-preview", "image", "video", "audio-generation"],
  "media-analysis": ["text", "text-preview", "image", "video"],
  "text-preview": ["text", "image", "video", "audio-generation"],
  image: ["media-analysis", "image", "video", "preview", "output"],
  asset: ["video"],
  merge: ["text", "media-analysis", "image", "video", "preview"],
  video: ["media-analysis", "preview", "output"],
  preview: ["media-analysis", "image", "video", "output"],
};

function quickExtensionKinds(kind, direction) {
  if (direction === "after") return QUICK_NEXT_NODE_KINDS[kind] || [];
  return Object.entries(QUICK_NEXT_NODE_KINDS)
    .filter(([, nextKinds]) => nextKinds.includes(kind))
    .map(([sourceKind]) => sourceKind);
}

function menuItemSupportsKind(item, kind) {
  return item.kind === kind || item.variantKinds?.includes(kind);
}

function resolveMenuItemKind(item, compatibleKinds = []) {
  return (
    compatibleKinds.find((kind) => menuItemSupportsKind(item, kind)) ||
    item.createKind ||
    item.kind
  );
}

function firstCompatiblePortPair(sourceData, targetData) {
  for (const sourcePort of sourceData?.outputs || []) {
    for (const targetPort of targetData?.inputs || []) {
      if (
        sourcePort.type === "ANY" ||
        targetPort.type === "ANY" ||
        sourcePort.type === targetPort.type
      ) {
        return { sourceHandle: sourcePort.id, targetHandle: targetPort.id };
      }
    }
  }
  return null;
}

const QUICK_MATERIAL_SOURCE_KINDS = new Set([
  "text-input",
  "input",
  "batch-input",
  "face-input",
  "person-video-input",
  "text",
  "media-analysis",
  "text-preview",
  "image",
  "video",
  "preview",
]);

function quickMaterialSource(node) {
  if (!QUICK_MATERIAL_SOURCE_KINDS.has(node?.data?.kind)) return null;
  const previews = Array.isArray(node.data.runtimePreviews)
    ? node.data.runtimePreviews
    : [];
  const previewKinds = new Set(previews.map((preview) => preview.kind));
  const outputs = Array.isArray(node.data.outputs) ? node.data.outputs : [];
  const port =
    outputs.find((output) => output.type === "TEXT") ||
    outputs.find((output) => output.type === "IMAGE") ||
    outputs.find((output) => output.type === "VIDEO") ||
    outputs.find((output) => output.type === "ANY");
  if (!port) return null;
  const type =
    previewKinds.size === 1 && previewKinds.has("video")
      ? "VIDEO"
      : previewKinds.has("image")
        ? "IMAGE"
        : port.type;
  return { node, sourceHandle: port.id, type };
}

function compareMaterialSources(left, right) {
  const leftGroup = String(left?.node?.data?.gridSplitOrigin?.requestId || "");
  const rightGroup = String(right?.node?.data?.gridSplitOrigin?.requestId || "");
  const leftOrder = Number(left?.node?.data?.gridSplitOrigin?.order);
  const rightOrder = Number(right?.node?.data?.gridSplitOrigin?.order);
  const hasLeftOrder = Number.isFinite(leftOrder) && leftOrder > 0;
  const hasRightOrder = Number.isFinite(rightOrder) && rightOrder > 0;
  if (hasLeftOrder || hasRightOrder) {
    if (hasLeftOrder && hasRightOrder && leftGroup !== rightGroup)
      return leftGroup.localeCompare(rightGroup, "zh-CN", { numeric: true });
    if (hasLeftOrder && hasRightOrder && leftOrder !== rightOrder)
      return leftOrder - rightOrder;
    if (hasLeftOrder !== hasRightOrder) return hasLeftOrder ? -1 : 1;
  }
  return (
    Number(left?.node?.position?.x || 0) -
      Number(right?.node?.position?.x || 0) ||
    Number(left?.node?.position?.y || 0) -
      Number(right?.node?.position?.y || 0)
  );
}

