function PublishInspirationModal({ template, notify, onClose, onPublished }) {
  const [title, setTitle] = useState(template?.name || "");
  const [inspirationKind, setInspirationKind] = useState(
    /搭配图|自动搭配|搭配设计|智能搭配/.test(
      `${template?.name || ""} ${template?.category || ""}`,
    )
      ? "outfit"
      : orderedTemplateNodes(template)
            .map((node) => node.data?.kind)
            .filter((kind) => ["image", "video"].includes(kind))
            .at(-1) === "image"
        ? "image"
        : "video",
  );
  const [description, setDescription] = useState("");
  const [tags, setTags] = useState("");
  const [ratio, setRatio] = useState("9:16");
  const [cover, setCover] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const previewUrl = useMemo(
    () => (cover instanceof File ? URL.createObjectURL(cover) : ""),
    [cover],
  );
  useEffect(
    () => () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    },
    [previewUrl],
  );
  const fields = inspirationWorkflowFieldSummary(template);
  const mediaType = useMemo(() => {
    const generationKinds = orderedTemplateNodes(template)
      .map((node) => node.data?.kind)
      .filter((kind) => ["image", "video"].includes(kind));
    return generationKinds[generationKinds.length - 1] === "image"
      ? "image"
      : "video";
  }, [template]);
  const selectedInspirationKindLabel = inspirationKindLabel(inspirationKind);
  const publish = async () => {
    if (!title.trim()) return notify("请输入案例名称", "error");
    if (!(cover instanceof File)) return notify("请上传案例封面", "error");
    setSubmitting(true);
    try {
      const result = await api.createInspiration({
        title: title.trim(),
        kind: inspirationKind,
        description: description.trim(),
        tags,
        ratio,
        workflowTemplateId: template.id,
        coverImage: await fileToBase64(cover),
        coverMimeType: cover.type,
      });
      notify(`案例「${result.title}」已发布到模版`, "success");
      onPublished(result);
    } catch (error) {
      notify(error.message, "error");
    } finally {
      setSubmitting(false);
    }
  };
  return (
    <div className="modal-backdrop" onMouseDown={onClose}>
      <section
        className="run-modal publish-inspiration-modal"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <div className="modal-head">
          <div>
            <span className="eyebrow">PUBLISH TEMPLATE</span>
            <h2>发布到模版</h2>
            <p>案例会固化当前工作流；用户点击一键同款后按开放节点填写素材。</p>
          </div>
          <button
            className="icon-button"
            onClick={onClose}
            aria-label="关闭发布弹层"
            title="关闭"
          >
            <X size={18} />
          </button>
        </div>
        <div className="publish-chain" aria-label="发布链路">
          {["保存画布", "固化节点", "发布模版库", "支持一键同款"].map((label, index) => (
            <span key={label}>
              <b>{index + 1}</b>{label}
            </span>
          ))}
        </div>
        <div className="publish-inspiration-layout">
          <label className="publish-inspiration-cover">
            {previewUrl ? (
              <img src={previewUrl} alt="案例封面预览" />
            ) : (
              <span><ImageIcon size={24} />上传案例封面<small>JPG / PNG / WebP · 最大 24MB</small></span>
            )}
            <input
              type="file"
              accept="image/jpeg,image/png,image/webp"
              onChange={(event) => setCover(event.target.files?.[0] || null)}
            />
          </label>
          <div className="publish-inspiration-fields">
            <label className="form-field"><span>案例名称</span><input value={title} onChange={(event) => setTitle(event.target.value)} /></label>
            <div className="publish-inspiration-row">
              <div className="form-field">
                <span id="publish-inspiration-kind-label">模版分类</span>
                <div
                  className="publish-inspiration-kind-options"
                  role="radiogroup"
                  aria-labelledby="publish-inspiration-kind-label"
                >
                  {[
                    ["outfit", "搭配图"],
                    ["image", "详情页"],
                    ["video", "视频模版"],
                    ["qianchuan", "素材同款"],
                  ].map(([value, label]) => (
                    <button
                      type="button"
                      role="radio"
                      aria-checked={inspirationKind === value}
                      className={inspirationKind === value ? "active" : ""}
                      key={value}
                      onClick={() => setInspirationKind(value)}
                    >
                      {label}
                    </button>
                  ))}
                </div>
              </div>
              <label className="form-field"><span>画幅</span><select value={ratio} onChange={(event) => setRatio(event.target.value)}><option>9:16</option><option>16:9</option><option>1:1</option><option>3:4</option><option>4:3</option></select></label>
            </div>
            <label className="form-field"><span>标签（逗号分隔）</span><input value={tags} onChange={(event) => setTags(event.target.value)} placeholder="女装, 口播, 商品展示" /></label>
            <label className="form-field"><span>案例说明</span><textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="说明案例效果和用户需要准备的素材" /></label>
          </div>
        </div>
        <div className="publish-workflow-summary">
          {mediaType === "image" ? <ImageIcon size={16} /> : <Film size={16} />}
          <span><strong>{template.name}</strong><small>{selectedInspirationKindLabel} · 输出{mediaType === "image" ? "图片" : "视频"} · {fields.media} 个素材节点 · {fields.text} 个文案节点 · {fields.required} 个必填</small></span>
        </div>
        <div className="modal-footer">
          <button className="secondary-button" onClick={onClose}>取消</button>
          <button className="primary-button" disabled={submitting} onClick={publish}>
            {submitting ? <LoaderCircle className="spin" size={16} /> : <Sparkles size={16} />}
            {submitting ? "正在发布" : "发布到模版"}
          </button>
        </div>
      </section>
    </div>
  );
}

const EMPTY_CAPABILITIES = {
  klingConfigured: false,
  deepSeekConfigured: false,
  image2Configured: false,
  vapeurConfigured: false,
  vapeurImageConfigured: false,
  minimaxAudioConfigured: false,
  minimaxVideoConfigured: false,
  volcengine: { ready: false },
};

