      const vertical = guides.vertical
        ? (() => {
            const start = flowInstance.flowToScreenPosition({
              x: guides.vertical.x,
              y: guides.vertical.from,
            });
            const end = flowInstance.flowToScreenPosition({
              x: guides.vertical.x,
              y: guides.vertical.to,
            });
            return {
              left: start.x - canvasRect.left,
              top: Math.min(start.y, end.y) - canvasRect.top,
              height: Math.abs(end.y - start.y),
            };
          })()
        : null;
