  const replaceNodeFilesFromDrop = async (targetNode, fileList) => {
    const generationMediaNode = ["image", "video"].includes(
      targetNode?.data?.kind,
    );
    if (
      !targetNode ||
      (!WORKFLOW_DIRECT_REPLACE_KINDS.has(targetNode.data?.kind) &&
        !targetNode.data?.directMediaInput &&
        !generationMediaNode)
    )
      return false;
    const files = Array.from(fileList || []);
    if (!files.length) return false;
    const kind = targetNode.data.kind;
    let validation;
    if (targetNode.data?.directMediaInput || generationMediaNode) {
      validation =
        kind === "image"
          ? validateMediaFiles(files, ["image"], { image: 4 })
          : validateMediaFiles(files, ["image", "video"], {
              image: videoImageSlotLimit(targetNode.data?.model),
              video: 1,
            });
    } else if (kind === "face-input") {
      validation = validateMediaFiles(files, ["image"], { image: 9 });
    } else if (kind === "person-video-input") {
      const compatible = files.filter(
        (file) =>
          ["video/mp4", "video/quicktime"].includes(file.type) ||
          ["mp4", "mov"].includes(fileExtension(file)),
      );
      validation = validateSeedanceFiles(compatible, "video", 1);
      validation.rejected.unshift(
        ...files
          .filter((file) => !compatible.includes(file))
          .map(
            (file) => `${file.name} 不能作为真人人物视频，仅支持 MP4 或 MOV`,
          ),
      );
    } else if (kind === "batch-input") {
      validation = validateMediaFiles(files, ["image"], { image: 50 });
    } else {
      const limits = { image: 9, video: 3 };
      validation = feedsSeedanceNode(targetNode.id)
        ? validateSeedanceMixedFiles(files, ["image", "video"], limits)
        : feedsMediaAnalysisNode(targetNode.id)
          ? validateAnalysisMixedFiles(files, limits)
          : validateMediaFiles(files, ["image", "video"], limits);
    }
    const { accepted, rejected } = validation;
    if (rejected.length) notify(rejected[0], "error");
    if (!accepted.length) return false;
    const inspected = await Promise.all(accepted.map(inspectMediaAsset));
    const next =
      kind === "person-video-input" ? inspected.slice(0, 1) : inspected;
    checkpointWorkflow("replace-node-media");
    setNodeFiles((current) => ({ ...current, [targetNode.id]: next }));
    if (generationMediaNode && !targetNode.data?.directMediaInput)
      setNodes((current) =>
        current.map((node) =>
          node.id === targetNode.id
            ? { ...node, data: { ...node.data, directMediaInput: true } }
            : node,
        ),
      );
    updateRuntimeMedia(targetNode.id, next);
    setSelectedId(targetNode.id);
    setSelectedEdgeId(null);
    setContextMenu(null);
    notify(
      `已拖拽替换「${targetNode.data.title || "输入节点"}」的 ${next.length} 个素材`,
      "success",
    );
    return true;
  };
  const chooseBatchFolder = async () => {
    if (!selected || selected.data.kind !== "batch-input") return;
    const applyFiles = async (files, folderName = "批量文件夹") => {
      const { accepted, rejected } = validateMediaFiles(files, ["image"], {
        image: 50,
      });
      if (rejected.length) notify(rejected[0], "info");
      if (!accepted.length)
        return notify("文件夹内没有可用的 JPG、PNG 或 WebP 图片", "error");
      const media = await Promise.all(accepted.map(inspectMediaAsset));
      checkpointWorkflow();
      setNodeFiles((current) => ({ ...current, [selected.id]: media }));
      updateRuntimeMedia(selected.id, media);
      updateSelected({
        folderName,
        title: folderName,
        subtitle: `${media.length} 张图片 · 将运行 ${media.length} 次工作流`,
      });
      notify(
        `已绑定文件夹「${folderName}」，共 ${media.length} 张图片`,
        "success",
      );
    };
    if (window.showDirectoryPicker) {
      try {
        const directory = await window.showDirectoryPicker({ mode: "read" });
        const files = [];
        const collect = async (handle) => {
          for await (const entry of handle.values()) {
            if (files.length >= 50) break;
            if (entry.kind === "file") {
              const file = await entry.getFile();
              const extension = file.name.split(".").pop()?.toLowerCase();
              const inferredType =
                {
                  jpg: "image/jpeg",
                  jpeg: "image/jpeg",
                  png: "image/png",
                  webp: "image/webp",
                }[extension] || file.type;
              files.push(
                file.type
                  ? file
                  : new File([file], file.name, {
                      type: inferredType,
                      lastModified: file.lastModified,
                    }),
              );
            } else if (entry.kind === "directory") await collect(entry);
          }
        };
        await collect(directory);
        files.sort((left, right) =>
          left.name.localeCompare(right.name, "zh-CN", {
            numeric: true,
            sensitivity: "base",
          }),
        );
        await applyFiles(files, directory.name);
      } catch (error) {
        if (error?.name !== "AbortError")
          notify(error.message || "读取文件夹失败", "error");
      }
      return;
    }
    const picker = document.createElement("input");
    picker.type = "file";
    picker.multiple = true;
    picker.accept = "image/jpeg,image/png,image/webp";
    picker.webkitdirectory = true;
    picker.onchange = () =>
      void applyFiles(
        Array.from(picker.files || []).sort((left, right) =>
          left.name.localeCompare(right.name, "zh-CN", {
            numeric: true,
            sensitivity: "base",
          }),
        ),
        picker.files?.[0]?.webkitRelativePath?.split("/")[0] || "批量文件夹",
      );
    picker.click();
  };
